function useMenu() {
  const [open, setOpen] = useState(false);
  const toggle = () => setOpen((v) => !v);

  const getTriggerProps = (props = {}) => ({
    "aria-expanded": open,
    onClick: toggle,
    ...props, // spread caller props LAST
  });

  // convenience: a ready-made menu panel
  const MenuPanel = ({ children }: { children: React.ReactNode }) =>
    open ? <ul className="menu-panel">{children}</ul> : null;

  return { open, toggle, getTriggerProps, MenuPanel };
}
